#include<bits/stdc++.h>
#define int long long
using namespace std;
const int N=5e5+10;
int n,m;
int v[N],a[N],ans[N];
signed main(){
	freopen("card.in","r",stdin);
	freopen("card.out","w",stdout);
	cin>>n>>m;
	for(int i=1;i<=n;i++)cin>>a[i];
	for(int i=n;i>=1;i--){
		if(v[a[i]]==0)v[a[i]]=i;
	}
	int lst=1;
	for(int i=1;i<=n;i++){
		ans[a[i]]++;
		int cnt=1;
		if(v[a[i-1]]>i||a[i]==a[i-1]){
			lst=i;
			//cout<<cnt<<' ';
			continue;
		}
		ans[a[i]]+=(i-lst);cnt+=(i-lst);
		for(int j=lst-1;j>=1;j--){
			if(v[a[j]]>i||a[i]==a[j]){
				lst=j+1;
				j=0;
			}else ans[a[i]]++;cnt++;
		}
		//cout<<cnt<<' ';
	}
	//cout<<endl;
	ans[a[n]]=n;
	for(int i=1;i<=m;i++){
		cout<<ans[i]<<' ';
	}
	return 0;
}
